import type { DistanceClassification } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface DistanceClassificationEntry {
  label: string;
  variant: BadgeVariants;
}

export const distanceClassificationConfig: Record<DistanceClassification, DistanceClassificationEntry> = {
  local: { label: 'Local', variant: 'success' },
  qrf: { label: 'QRF', variant: 'info' },
};

const defaultEntry: DistanceClassificationEntry = { label: '', variant: 'default' };

export function getDistanceClassification(value: DistanceClassification): DistanceClassificationEntry {
  return distanceClassificationConfig[value] ?? { ...defaultEntry, label: snakeCaseToCapitalizedCase(value) };
}
